import json,pathlib
from datetime import datetime,timedelta
import pandas as pd
B=pathlib.Path('/app/dataset')
farms=pd.read_csv(B/'farms.csv'); farms['key']=farms.farm_name.str.strip().str.lower(); reg=pd.read_csv(B/'farm_registry.csv'); meta=reg.merge(farms,left_on='farm_name',right_on='key')
cal=json.loads((B/'sensors_calibration.json').read_text())['enterprise_platform']['deployment_environments']['system_config']['farms']
maint={'FARM_C':[(pd.Timestamp('2024-03-16 08:00'),pd.Timestamp('2024-03-16 12:00'))], 'FARM_F':[(pd.Timestamp('2024-03-15 12:00'),pd.Timestamp('2024-03-15 14:00'))]}

def num(x,semi):
 if pd.isna(x):return float('nan')
 s=str(x).strip()
 if semi and ',' in s:s=s.replace('.','').replace(',','.')
 try:return float(s)
 except:return float('nan')

def calc(keep='last',localtz=True,do_maint=True):
 out={}; details={}
 for _,m in meta.iterrows():
  fid=m.farm_id; p=B/f'production_{fid}.csv'; b=p.read_bytes(); enc='utf-16' if b.startswith((b'\xff\xfe',b'\xfe\xff')) else 'utf-8'; h=b.decode(enc).splitlines()[3]; semi=h.count(';')>h.count(','); sep=';' if semi else ','
  d=pd.read_csv(p,encoding=enc,skiprows=3,sep=sep,dtype=str); tscol=d.columns[0]
  d['_local']=pd.to_datetime(d[tscol],format='mixed',errors='coerce'); d=d[d._local.notna()].drop_duplicates('_local',keep=keep).copy()
  cadence=d._local.sort_values().diff().dt.total_seconds().div(3600); cadence=float(cadence[cadence>0].mode().iloc[0])
  if localtz:d['_utc']=d._local.dt.tz_localize(m.timezone).dt.tz_convert('UTC')
  else:d['_utc']=d._local.dt.tz_localize('UTC')
  cfg=cal[fid]; off=cfg['calibration_data']['calibration_offset']; col=cfg['calibration_data']['value_column_name']; d['_true']=d[col].map(lambda x:num(x,semi))-off; d['_temp']=d['inverter_temperature_C'].map(lambda x:num(x,semi))
  inwin=(d._utc>=pd.Timestamp('2024-03-15',tz='UTC'))&(d._utc<pd.Timestamp('2024-03-16',tz='UTC'))
  neg=(d._true<0); valid=inwin&d._true.notna()&~neg
  mexcl=pd.Series(False,index=d.index)
  if do_maint:
   for a,z in maint.get(fid,[]):mexcl |= (d._local>=a)&(d._local<z)
   valid &= ~mexcl
  # safety after spikes, none in data
  spikes=d.loc[d._temp>85,'_utc']
  sexcl=pd.Series(False,index=d.index)
  for s in spikes: sexcl |= (d._utc>s)&(d._utc<=s+pd.Timedelta(minutes=45))
  valid &= ~sexcl
  vals=d.loc[valid,'_true']; unit=cfg['sensor_info']['unit'].lower(); typ=cfg['sensor_info']['reading_type'].lower()
  factor={'wh':.001,'kwh':1,'mwh':1000,'btu':.00029307107}[unit]
  total=vals.sum()*factor*(cadence if typ=='power' else 1)
  out[fid]=round(total)
  details[fid]=(round(total,3),int(inwin.sum()),int(valid.sum()),int((inwin&mexcl).sum()),cadence)
 return out,details
for k,lt,ma in [('last-local-maint','last',True,True),('first-local-maint','first',True,True),('last-utc-maint','last',False,True),('last-local-nomaint','last',True,False)]:
 o,d=calc(lt,localtz=('local' in k and 'utc' not in k),do_maint=ma)
 print(k,o)
 if k=='last-local-maint':
  for x in o: print(x,d[x])
